// Generated by Cypress Author — 2026-11-14
// All destination constants were recorded before activation in inspection/baseline.json.
// /shop checks are dated baseline regressions; intended K1 policy remains unapproved.
import { routes, desktopNav, home, shop, product, login, missing, visit, sections, section } from '../../../support/navigation';

describe('M01 real guest navigation — recorded baseline subsets', () => {
  it('N01-TC03 — subset: home → direct login → direct home without submission', () => {
    visit(routes.home); home();
    cy.visit(routes.login); login();
    cy.visit(routes.home); home();
  });

  const targets = [
    { name: 'packages page', href: '/shop', verify: shop },
    ...sections.slice(1).map(row => ({ name: row.hash, href: '/' + row.hash, verify: () => section(row) }))
  ];
  targets.forEach(row => {
    it('N02-TC01 — subset baseline: home header → ' + row.name, () => {
      visit(routes.home); home();
      cy.get(desktopNav + ' a[href="' + row.href + '"]').click();
      row.verify();
    });
    it('N02-TC04 — subset baseline: product header → ' + row.name, () => {
      visit(routes.product); product();
      cy.get(desktopNav + ' a[href="' + row.href + '"]').click();
      row.verify();
    });
  });

  sections.slice(0, 2).forEach((row, index) => {
    it('N02-TC02 — subset baseline: hero CTA → ' + row.hash, () => {
      visit(routes.home); home();
      cy.contains('main a', index === 0 ? 'دیدن بسته‌ها' : 'آشنایی با فرایند').click();
      section(row);
    });
  });
  ['مشاهدهٔ همهٔ بسته‌ها', 'بسته‌ها را ببینید'].forEach(text => {
    it('N02-TC02 — subset baseline: ' + text + ' → shop page', () => {
      visit(routes.home); home();
      cy.contains('main a', text).click();
      shop();
    });
  });

  sections.slice(1).forEach(row => {
    it('N02-TC03 — subset: direct home fragment renders its own section ' + row.hash, () => {
      visit('/' + row.hash);
      section(row);
    });
  });

  it('N02-TC05 — subset: focused real section link activates with Enter', () => {
    visit(routes.home); home();
    const row = sections[1];
    cy.get(desktopNav + ' a[href="/#how-it-works"]').focus().should('have.focus');
    cy.press(Cypress.Keyboard.Keys.ENTER);
    section(row);
    // Programmatic focus does not establish Tab traversal or visible focus quality.
  });
  it('N03-TC01 — subset: product logo → distinct home content', () => {
    visit(routes.product); product();
    cy.get('header a[aria-label="EZpost، صفحهٔ اصلی"]').click();
    home();
  });
  [
    { href: '/', verify: home },
    { href: '/shop', verify: shop }
  ].forEach(row => {
    it('N03-TC02 — subset baseline: product breadcrumb → ' + row.href, () => {
      visit(routes.product); product();
      cy.get('main nav[aria-label="مسیر صفحه"] a[href="' + row.href + '"]').click();
      row.verify();
    });
  });
  it('N03-TC03 — subset baseline: login return → home, no form submission', () => {
    visit(routes.login); login();
    cy.contains('main a[href="/"]', 'بازگشت به فروشگاه').click();
    home();
  });
  [1366, 390].forEach(width => {
    it('N03-TC04 — subset: footer top restores home hero at viewport ' + width, () => {
      cy.viewport(width, width === 390 ? 844 : 900);
      visit(routes.home); home();
      cy.contains('footer a', 'بازگشت به بالا').scrollIntoView().click();
      home();
      cy.get('main h1').should($h1 => {
        const rect = $h1[0].getBoundingClientRect();
        expect(rect.top, 'hero returns inside viewport').greaterThan(-1);
        expect(rect.bottom, 'hero remains in viewport').lessThan($h1[0].ownerDocument.defaultView.innerHeight);
      });
      cy.screenshot('N03-TC04-top-' + width, { capture: 'viewport' });
    });
  });
  it('N04-TC01 — subset: real product link, Back and Forward restore distinct pages', () => {
    visit(routes.home); home();
    cy.get('main a[href="' + routes.product + '"]').click();
    product();
    cy.go('back'); home();
    cy.go('forward'); product();
  });
  it('N04-TC02 — subset: direct product reload preserves route/content coherence', () => {
    visit(routes.product); product();
    cy.reload(); product();
  });
  it('N07-TC01 — subset: missing product displays Persian error and recovery control', () => {
    visit(routes.missing); missing();
    cy.screenshot('N07-TC01-missing');
  });
  it('N07-TC02 — subset baseline: error recovery → distinct home, not stale error', () => {
    visit(routes.missing); missing();
    cy.contains('main button', 'بازگشت به فروشگاه').click();
    home();
    cy.get('main > p').should('not.exist');
  });
  it('N07-TC03 — subset: missing product reload retains recognizable recoverable error', () => {
    visit(routes.missing); missing();
    cy.reload({ failOnStatusCode: false }); missing();
  });
  it('N07-TC04 — subset: deliberate native suffix supports Back/Forward after recovery', () => {
    visit(routes.missing); missing();
    cy.contains('main button', 'بازگشت به فروشگاه').click(); home();
    cy.window().then(win => { win.location.assign(routes.product); }); product();
    cy.window().then(win => { win.location.assign(routes.missing); }); missing();
    cy.go('back'); product();
    cy.go('back'); home();
    cy.go('forward'); product();
    cy.go('forward'); missing();
    // No history API injection and no assumption about recovery push vs replace.
  });
  [sections[0], sections[1], sections[2]].forEach((row, index) => {
    it('N02-TC01 — narrow subset: mobile menu → ' + (index === 0 ? 'shop' : row.hash), () => {
      cy.viewport(390, 844);
      visit(routes.home); home();
      cy.get('header summary[aria-label="باز کردن فهرست"]').click();
      const href = index === 0 ? '/shop' : '/' + row.hash;
      cy.get('nav[aria-label="ناوبری موبایل"] a[href="' + href + '"]').should('be.visible').click();
      if (index === 0) shop(); else section(row);
      cy.screenshot('N02-TC01-narrow-' + index, { capture: 'viewport' });
    });
  });
});

